    const dow = day.getUTCDay(), wk = week(L, day), tk = `${wk}-${dow}`, sun = H.temp[`${wk}-0`] || {}, tmp = H.temp[tk] || {}, D = H.days[dow][which];
    const key = which === 'L' ? 'A2' : 'A3';
    const ant = tmp[key] || (dow === 0 ? sun[key] : '') || D.ant;
    const coll = tmp.O || sun.O || '';
    const cap = (which === 'L' ? tmp.C || (dow === 0 ? sun.C : '') : '') || D.cap;
    const hymn = seasonHymn(wk, which) || D.hymn;
    const name = which === 'L' ? 'Lauds' : 'Vespers', cant = which === 'L' ? '231' : '232', cname = which === 'L' ? 'Benedictus' : 'Magnificat';
    let h = `<p class="muted" style="font-size:.82rem">${first ? 'First Vespers of Sunday. ' : ''}Traditional ${name} · weekly psalter · Douay psalm numbers. Saints’ days are not included.</p>`;
    h += `<div class="sec"><b>Opening</b>${lines(H.g['Deus in adjutorium'])}</div>`;
    h += '<div class="sec"><b>Psalms</b>' + D.psalms.map(([a, ref]) => `<div class="ant"><i>Ant.</i> ${esc(a)}</div>${psalmHTML(ref)}`).join('') + '</div>';
    if (cap) h += `<div class="sec"><b>Chapter</b>${lines(cap)}</div>`;
    if (D.resp) h += `<div class="sec"><b>Short responsory</b>${lines(D.resp)}</div>`;
    if (hymn) h += `<div class="sec"><b>Hymn</b>${lines(hymn)}</div>`;
    if (D.vers) h += `<div class="sec"><b>Versicle</b>${lines(D.vers)}</div>`;
